.darma-loader-darma-b14-noodle-twirl { --accent: var(--loader-color, #fbbf24); --accent-2: var(--loader-secondary-color, #0f766e); width: var(--loader-size, 112px); height: calc(var(--loader-size, 112px) * .82); position: relative; }
.darma-loader-darma-b14-noodle-twirl::after { content: ''; position: absolute; bottom: 0; left: 4%; width: 92%; height: 32%; border-radius: 0 0 50% 50% / 0 0 100% 100%; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 34%, var(--accent-2))); }
.darma-loader-darma-b14-noodle-twirl::before { content: ''; position: absolute; bottom: 27%; left: 8%; width: 84%; height: 13%; border-radius: 50%; background: radial-gradient(ellipse at 40% 30%, color-mix(in srgb, #fff 46%, var(--accent)), var(--accent)); }
.darma-loader-darma-b14-noodle-twirl .darma-loader-darma-b14-noodle-twirl__fork { position: absolute; z-index: 3; bottom: 36%; left: calc(50% - var(--loader-size, 112px) * .028); width: calc(var(--loader-size, 112px) * .056); height: 50%; border-radius: 2px 2px 0 0; transform-origin: bottom center; background: linear-gradient(90deg, #f8fafc, #94a3b8); animation: darma-loader-darma-b14-noodle-twirl-twirl calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
.darma-loader-darma-b14-noodle-twirl .darma-loader-darma-b14-noodle-twirl__fork::after { content: ''; position: absolute; top: 100%; left: -110%; width: 320%; height: calc(var(--loader-size, 112px) * .1); background: repeating-linear-gradient(90deg, #cbd5e1 0 24%, transparent 24% 38%); }
.darma-loader-darma-b14-noodle-twirl span { position: absolute; z-index: 2; bottom: 30%; left: 30%; width: 40%; height: 17%; border-radius: 50%; border: calc(var(--loader-size, 112px) * .035) solid var(--accent); border-top-color: transparent; animation: darma-loader-darma-b14-noodle-twirl-wrap calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
.darma-loader-darma-b14-noodle-twirl span:nth-child(3) { bottom: 38%; left: 36%; width: 28%; height: 13%; border-color: color-mix(in srgb, #fff 30%, var(--accent)); border-bottom-color: transparent; animation-duration: calc(var(--loader-speed, 1s) * 1.1); }
@keyframes darma-loader-darma-b14-noodle-twirl-twirl { to { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b14-noodle-twirl-wrap { to { transform: rotate(-360deg); } }

